import type {TaskLeaderboard} from './types';
import toolUseCorrectness from './results/tool-use-correctness.json';

/**
 * One leaderboard per task, regenerated by `llmsearchbench publish` from the
 * recorded attempts. Adding a task means adding a file and a line here.
 */
export const leaderboards: Record<string, TaskLeaderboard> = {
  'tool-use-correctness': toolUseCorrectness as TaskLeaderboard,
};

export const taskIds = Object.keys(leaderboards);

export function getLeaderboard(task: string): TaskLeaderboard {
  const board = leaderboards[task];
  if (!board) {
    throw new Error(`Unknown task "${task}". Known: ${taskIds.join(', ')}`);
  }
  return board;
}

export type {LeaderboardRow, TaskLeaderboard} from './types';
